udy: Some(ProfileStudy {\\n+            run_id: \\\"12345\\\".into(),\\n+            run_attempt: 1,\\n+            mutation_profile: profile.into(),\\n+            fanout,\\n+        }),\\n+        files: if fanout.is_some() {\\n+            vec![1000]\\n+        } else {\\n+            vec![60]\\n+        },\\n+        shard: Some(ScaleShard { index: 0, count: 1 }),\\n+        skip_fanout: fanout.is_none(),\\n+        dirty_budget: 8,\\n+        max_resume_builds: 128,\\n+        fanouts: vec![1, 4, 16, 64, 128],\\n+        ..ScalePlan::default()\\n+    }\\n+}\\n+\\n+#[test]\\n+fn isolated_profile_wire_cannot_select_another_protocol_or_omit_its_identity() {\\n+    let old = serde_json::to_value(ScalePlan::default()).unwrap();\\n+    assert!(old.get(\\\"profile_study\\\").is_none());\\n+    assert!(old.get(\\\"stage_scope\\\").is_none());\\n+    let mut plan = isolated_smoke(\\\"body\\\", None);\\n+    plan.validate().unwrap();\\n+    let wire = serde_json::to_value(&plan).unwrap();\\n+    let decoded: ScalePlan = serde_json::from_value(wire.clone()).unwrap();\\n+    assert_eq!(serde_json::to_value(decoded).unwrap(), wire);\\n+    plan.profile_study.as_mut().unwrap().mutation_profile = \\\"cold\\\".into();\\n+    assert!(plan.validate().is_err());\\n+    plan = isolated_smoke(\\\"body\\\", None);\\n+    plan.cold_study = Some(ColdStudy {\\n+        run_id: \\\"12345\\\".into(),\\n+        run_attempt: 1,\\n+    });\\n+    assert!(plan.validate().is_err());\\n+    plan.cold_study = None;\\n+    plan.stage_scope = None;\\n+    assert!(plan.validate().is_err());\\n+    plan = isolated_smoke(\\\"fanout\\\", Some(16));\\n+    plan.validate().unwrap();\\n+    plan.skip_fanout = true;\\n+    assert!(plan.validate().is_err());\\n+}\\n+\\n+#[test]\\n+fn isolated_fresh_batch_keeps_original_target_and_both_full_parity_checkpoints() {\\n+    let temp = tempfile::tempdir().unwrap();\\n+    let out = temp.path().join(\\\"fresh-batch\\\");\\n+    let plan = isolated_smoke(\\\"batch_1\\\", None);\\n+    let report = p8_scale::run_supervised(&plan, &out, binary()).unwrap();\\n+    assert_eq!(report[\\\"exit_code\\\"], 0, \\\"{report}\\\");\\n+    assert_eq!(report[\\\"summary\\\"][\\\"stage_scope\\\"], \\\"profile_isolated_v1\\\");\\n+    assert_eq!(report[\\\"summary\\\"][\\\"sample_count\\\"], 2);\\n+    let rows: Vec<Value> = std::fs::read_to_string(out.join(\\\"raw.jsonl\\\"))\\n+        .unwrap()\\n+        .lines()\\n+        .map(|line| serde_json::from_str(line).unwrap())\\n+        .collect();\\n+    assert_eq!(rows[0][\\\"plan\\\"], serde_json::to_value(&plan).unwrap());\\n+    let initial = rows\\n+        .iter()\\n+        .find(|row| row[\\\"event\\\"] == \\\"cold_parity\\\")\\n+        .unwrap();\\n+    let stages: Vec<_> = rows\\n+        .iter()\\n+        .filter(|row| row[\\\"event\\\"] == \\\"stage_finished\\\")\\n+        .collect();\\n+    assert_eq!(stages.len(), 1);\\n+    assert!(stages[0][\\\"label\\\"].as_str().unwrap().ends_with(\\\"/batch_1\\\"));\\n+    assert_eq!(\\n+        initial[\\\"independent_config_fact\\\"],\\n+        stages[0][\\\"independent_config_fact\\\"]\\n+    );\\n+    for point in [initial, stages[0]] {\\n+        assert_eq!(point[\\\"parity\\\"][\\\"equal\\\"], true);\\n+        assert_eq!(point[\\\"parity\\\"][\\\"tables\\\"].as_array().unwrap().len(), 15);\\n+        assert_eq!(point[\\\"independent_config_fact\\\"][\\\"passed\\\"], true);\\n+    }\\n+    let mutations: Vec<_> = rows\\n+        .iter()\\n+        .filter(|row| row[\\\"event\\\"] == \\\"mutation\\\")\\n+        .collect();\\n+    assert_eq!(mutations.len(), 1);\\n+    assert_eq!(mutations[0][\\\"operations\\\"].as_array().unwrap().len(), 1);\\n+    assert_eq!(\\n+        rows.iter()\\n+            .filter(|row| row[\\\"event\\\"] == \\\"build_finished\\\" && row[\\\"full\\\"] == true)\\n+            .count(),\\n+        3\\n+    );\\n+    assert!(rows.iter().all(|row| row[\\\"event\\\"] != \\\"fanout_started\\\"));\\n+}\\n+\\n+#[test]\\n+fn isolated_fanout_retains_actual_initial_and_final_tables_without_a_scale_corpus() {\\n+    let temp = tempfile::tempdir().unwrap();\\n+    let out = temp.path().join(\\\"fanout\\\");\\n+    let plan = isolated_smoke(\\\"fanout\\\", Some(16));\\n+    let report = p8_scale::run_supervised(&plan, &out, binary()).unwrap();\\n+    assert_eq!(report[\\\"exit_code\\\"], 0, \\\"{report}\\\");\\n+    assert_eq!(report[\\\"summary\\\"][\\\"sample_count\\\"], 1);\\n+    let rows: Vec<Value> = std::fs::read_to_string(out.join(\\\"raw.jsonl\\\"))\\n+        .unwrap()\\n+        .lines()\\n+        .map(|line| serde_json::from_str(line).unwrap())\\n+        .collect();\\n+    assert_eq!(rows.len(), 3);\\n+    assert_eq!(rows[1][\\\"event\\\"], \\\"fanout_started\\\");\\n+    assert_eq!(rows[1][\\\"case\\\"][\\\"initial\\\"].as_object().unwrap().len(), 17);\\n+    assert_eq!(rows[1][\\\"case\\\"][\\\"dirty_budget\\\"], 8);\\n+    assert_eq!(rows[1][\\\"case\\\"][\\\"max_resume_builds\\\"], 128);\\n+    assert_eq!(rows[2][\\\"first_build_incomplete\\\"], true);\\n+    let result = &rows[2][\\\"result\\\"];\\n+    let initial = &result[\\\"initial_evidence\\\"];\\n+    assert_eq!(initial[\\\"equal\\\"], true);\\n+    assert_eq!(initial[\\\"tables\\\"].as_array().unwrap().len(), 15);\\n+    assert_eq!(initial[\\\"incremental\\\"], initial[\\\"full\\\"]);\\n+    assert_eq!(\\n+        initial[\\\"incremental\\\"][\\\"files\\\"].as_array().unwrap().len(),\\n+        17\\n+    );\\n+    let point = &result[\\\"checkpoints\\\"][0];\\n+    assert_eq!(point[\\\"incremental\\\"], point[\\\"full\\\"]);\\n+    assert_eq!(point[\\\"truth\\\"].as_array().unwrap().len(), 16);\\n+    assert_eq!(\\n+        point[\\\"full_report\\\"][\\\"resolution_freshness\\\"][\\\"complete\\\"],\\n+        true\\n+    );\\n+}\\n+\\n+fn task_descriptive_plan(profile: &str, fanout: Option<usize>) -> ScalePlan {\\n+    ScalePlan {\\n+        profile: Profile::Release,\\n+        capacity_profile: Some(CapacityProfile::ScaleCapacityV1),\\n+        stage_scope: Some(StageScope::ProfileTaskDescriptiveV1),\\n+        profile_study: Some(ProfileStudy {\\n+            run_id: \\\"12345\\\".into(),\\n+            run_attempt: 1,\\n+            mutation_profile: profile.into(),\\n+            fanout,\\n+        }),\\n+        files: vec![1000],\\n+        repetitions: 1,\\n+        shard: Some(ScaleShard { index: 0, count: 1 }),\\n+        skip_fanout: fanout.is_none(),\\n+        dirty_budget: 200,\\n+        max_resume_builds: 1024,\\n+        batch_sizes: vec![1, 10, 100, 1000],\\n+        fanouts: vec![1, 4, 16, 64, 128],\\n+        deadline_ms: 18_000_000,\\n+        max_output_bytes: 512 * 1024 * 1024,\\n+        ..ScalePlan::default()\\n+    }\\n+}\\n+\\n+#[test]\\n+fn task_descriptive_scope_is_explicit_n1_without_weakening_old_n30() {\\n+    for profile in p8_scale::MUTATION_PROFILES {\\n+        for scale in RELEASE_SCALES {\\n+            let mut plan = task_descriptive_plan(profile, None);\\n+            plan.files = vec![scale];\\n+            let wire = serde_json::to_value(&plan).unwrap();\\n+            assert_eq!(wire[\\\"stage_scope\\\"], \\\"profile_task_descriptive_v1\\\");\\n+            let decoded: ScalePlan = serde_json::from_value(wire.clone()).unwrap();\\n+            assert_eq!(serde_json::to_value(&decoded).unwrap(), wire);\\n+            assert_eq!(decoded.fanout_budgets(), (8, 128));\\n+            // Debug binaries remain ineligible to execute any registered release cell.\\n+            assert_eq!(decoded.validate().is_ok(), !cfg!(debug_assertions));\\n+            if !cfg!(debug_assertions) {\\n+                assert_eq!(decoded.repetition_range().unwrap(), 0..1);\\n+            }\\n+            let mut wrong_scope = plan.clone();\\n+            wrong_scope.stage_scope = Some(StageScope::ProfileIsolatedV1);\\n+            assert!(wrong_scope.validate().is_err());\\n+            wrong_scope.repetitions = 30;\\n+            wrong_scope.shard = Some(ScaleShard { index: 0, count: 30 });\\n+            assert_eq!(wrong_scope.validate().is_ok(), !cfg!(debug_assertions));\\n+            wrong_scope.stage_scope = Some(StageScope::ProfileTaskDescriptiveV1);\\n+            assert!(wrong_scope.validate().is_err());\\n+        }\\n+    }\\n+    for fanout in [1, 4, 16, 64, 128] {\\n+        let plan = task_descriptive_plan(\\\"fanout\\\", Some(fanout));\\n+        assert_eq!(plan.validate().is_ok(), !cfg!(debug_assertions));\\n+        assert_eq!(plan.fanout_budgets(), (8, 128));\\n+    }\\n+}\\n+\\n+#[test]\\n+fn task_descriptive_scope_rejects_changed_identity_and_registered_budgets() {\\n+    let original = serde_json::to_value(task_descriptive_plan(\\\"body\\\", None)).unwrap();\\n+    for (key, replacement) in [\\n+        (\\\"profile\\\", json!(\\\"smoke\\\")),\\n+        (\\\"capacity_profile\\\", json!(\\\"scale_wide_dirty_v1\\\")),\\n+        (\\\"files\\\", json!([60])),\\n+        (\\\"seed\\\", json!(1)),\\n+        (\\\"repetitions\\\", json!(30)),\\n+        (\\\"shard\\\", json!({\\\"index\\\": 1, \\\"count\\\": 1})),\\n+        (\\\"shard\\\", json!({\\\"index\\\": 0, \\\"count\\\": 30})),\\n+        (\\\"dirty_budget\\\", json!(4096)),\\n+        (\\\"max_resume_builds\\\", json!(64)),\\n+        (\\\"deadline_ms\\\", json!(18_000_001)),\\n+        (\\\"max_output_bytes\\\", json!(256 * 1024 * 1024)),\\n+        (\\\"batch_sizes\\\", json!([1, 10])),\\n+        (\\\"fanouts\\\", json!([1, 4, 16])),\\n+        (\\\"profile_study\\\", Value::Null),\\n+        (\\\"cold_study\\\", json!({\\\"run_id\\\": \\\"12345\\\", \\\"run_attempt\\\": 1})),\\n+    ] {\\n+        let mut wire = original.clone();\\n+        wire[key] = replacement;\\n+        let plan: ScalePlan = serde_json::from_value(wire).unwrap();\\n+        assert!(plan.validate().is_err(), \\\"changed field {key}\\\");\\n+    }\\n+}\\n+\\n+#[test]\\n+fn task_descriptive_cli_does_not_launch_a_n30_or_mixed_scope_plan() {\\n+    for (scope, repetitions) in [\\n+        (\\\"profile_task_descriptive_v1\\\", \\\"30\\\"),\\n+        (\\\"profile_isolated_v1\\\", \\\"1\\\"),\\n+    ] {\\n+        let temp = tempfile::tempdir().unwrap();\\n+        let out = temp.path().join(\\\"must-not-start\\\");\\n+        let result = std::process::Command::new(binary())\\n+            .args([\\n+                \\\"--profile\\\",\\n+                \\\"release\\\",\\n+                \\\"--capacity-profile\\\",\\n+                \\\"scale_capacity_v1\\\",\\n+                \\\"--stage-scope\\\",\\n+                scope,\\n+                \\\"--study-run-id\\\",\\n+                \\\"12345\\\",\\n+                \\\"--study-attempt\\\",\\n+                \\\"1\\\",\\n+                \\\"--mutation-profile\\\",\\n+                \\\"body\\\",\\n+                \\\"--files\\\",\\n+                \\\"1000\\\",\\n+                \\\"--repetitions\\\",\\n+                repetitions,\\n+                \\\"--shard-index\\\",\\n+                \\\"0\\\",\\n+                \\\"--shard-count\\\",\\n+                repetitions,\\n+                \\\"--skip-fanout\\\",\\n+                \\\"--dirty-budget\\\",\\n+                \\\"200\\\",\\n+                \\\"--max-resume-builds\\\",\\n+                \\\"1024\\\",\\n+                \\\"--batch-sizes\\\",\\n+                \\\"1,10,100,1000\\\",\\n+                \\\"--fanouts\\\",\\n+                \\\"1,4,16,64,128\\\",\\n+                \\\"--deadline-ms\\\",\\n+                \\\"18000000\\\",\\n+                \\\"--max-output-bytes\\\",\\n+                \\\"536870912\\\",\\n+                \\\"--output\\\",\\n+            ])\\n+            .arg(&out)\\n+            .output()\\n+            .unwrap();\\n+        assert_eq!(result.status.code(), Some(2), \\\"{result:?}\\\");\\n+        assert!(!out.exists());\\n+    }\\n+}\"},{\"sha\":\"9934eb2d471ef5f5721fafcf538332dea64063b1\",\"filename\":\"docs/roadmap/code-index-v2/P8-PROFILE-ISOLATED.md\",\"status\":\"added\",\"additions\":75,\"deletions\":0,\"changes\":75,\"blob_url\":\"https://github.com/jyqj/codecortex/blob/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/docs%2Froadmap%2Fcode-index-v2%2FP8-PROFILE-ISOLATED.md\",\"raw_url\":\"https://github.com/jyqj/codecortex/raw/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/docs%2Froadmap%2Fcode-index-v2%2FP8-PROFILE-ISOLATED.md\",\"contents_url\":\"https://api.github.com/repos/jyqj/codecortex/contents/docs%2Froadmap%2Fcode-index-v2%2FP8-PROFILE-ISOLATED.md?ref=da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032\",\"patch\":\"@@ -0,0 +1,75 @@\\n+# Independent fresh-profile P8-006 study\\n+\\n+This is a new registered study. It does not repair, resume, relabel or reuse any\\n+part of a prior all-stage or cold-only study. The original default full runner,\\n+`scale_capacity_v1` artifacts, cold-only study and their outcomes remain intact.\\n+The machine-readable registration is `p8-profile-isolated-v1.json` in this directory.\\n+Neither this protocol nor a single successful slice closes a task automatically.\\n+\\n+The original P8-006 asks for no-op, body, API, config, batch and over-budget closure\\n+measurements, attributable phase counts, and complete full parity after closure.\\n+The original benchmark §8 starts each mutation with the same pristine A/B pair;\\n+§9 separates profiles and retains N>=30. This protocol registers exactly N30 for\\n+all eight mutation profiles on each of the original five scales: 1,200 cells.\\n+The separate fanout population is five values (1,4,16,64,128) x30 =150 cells,\\n+each with **actual N+1 files**. It is not multiplied by the five corpus scales.\\n+The fanout plan's `files=1000` is solely the existing conservative disk-reservation\\n+field; it does not claim a 1k fanout fixture.\\n+\\n+Every mutation cell generates two fresh projects, with empty index and parse\\n+cache, the same seed and original config augmentation. Both initial full builds,\\n+the complete initial 15-table comparison, one selected mutation, every original\\n+incremental/resume build, full-control rebuild and final complete 15-table parity\\n+are inside that worker's original five-hour deadline. Dirty/resume limits remain\\n+200/1024; fanout retains 8/128 and original handwritten call-edge assertions.\\n+The fanout evaluator additionally retains the already executed initial complete\\n+canonical comparison and original initial/full-control reports. Its existing\\n+ordinary entry's wire and correctness decisions remain unchanged.\\n+\\n+A fresh batch has not executed a preceding config mutation: its SQL config\\n+witness must still resolve target0. Only the config profile expects target1.\\n+The witness is retained and checked, not removed. Partial closure, parse errors,\\n+missing tables, failed native termination and truncated raw evidence cannot be\\n+accepted. The aggregate also retains the original requirement to observe an\\n+actual over-budget incomplete first fanout build that later completes.\\n+\\n+This explicitly changes history and the whole-study budget. It allows 1,350\\n+workers x5h =6,750 worker-hours, versus the original 150 sequential workers x5h\\n+=750 hours. It is **not an equivalent partition of that old budget or warm/cache\\n+history**. Each of the eight main profiles has a fresh setup; setup costs are\\n+retained, not taken outside the deadline. The 1,200 setup pairs carry no automatic\\n+P8-005 credit, and there is no P8-008 query credit. OS page cache is retained.\\n+\\n+The optional native `profile_study` and `profile_isolated_v1` scope are absent\\n+from old plans, preserving their serialized fields. New artifacts use only\\n+`p8-profile-*-${run_id}-${run_attempt}` names, with profile/scale-or-fanout/repetition\\n+slots. Old public full/cold validators still reject this scope; the new strict\\n+validator rejects full/cold slices and does not salvage failed prefixes.\\n+All 1,350 slots must bind one source, release binary, complete driver closure,\\n+build receipt, run ID and attempt. All raw rows, initial/final comparisons,\\n+phase counts, original worker resource snapshots, effective seed-cache cap,\\n+engine/runtime settings and temporary filesystem identities are retained.\\n+Snapshots are not peaks or process-tree coverage. Host/CPU/kernel/environment\\n+strata remain explicit; no pooled stable tail inference is added.\\n+\\n+The independent workflow is `.github/workflows/p8-profile.yml`, started only by\\n+its distinct `p8-profile-run` label event or explicit dispatch. It builds one\\n+release executable, then runs nine dependent matrices of 150 jobs each (eight\\n+mutation profiles and one fanout matrix). Each matrix is bounded to ten jobs;\\n+only one matrix is active at a time. Failure stops dependent matrices and the\\n+always-run aggregate rejects missing cells. There is no automatic new label,\\n+retry, source change or scheduler in the driver. Job timeout remains 350 minutes,\\n+while each supervised worker retains the original 5h and 512 MiB output budget.\\n+\\n+Build and intake commands use `scripts/p8_profile_matrix.py` with `build`, `run`\\n+and `aggregate` subcommands. A run requires the explicit `--mutation-profile`,\\n+`--scale`, `--shard-index`, `--run-id` and `--attempt`; fanout additionally requires\\n+`--fanout`. The normal build/hash/parity/source primitives are reused, not a new\\n+weaker comparison algorithm. The shared raw event validator checks every consumed\\n+build and the new independent population layer verifies every registered slot.\\n+\\n+The committed Python tests are synthetic protocol controls. Added Rust tests\\n+exercise fresh batch and actual small fanout contracts through the native worker.\\n+They are not release measurements. Candidate preparation does not execute or\\n+schedule this study; actual source admission, regression and explicit study\\n+execution remain separate, accurately attributed records.\"},{\"sha\":\"5cb2c5d144c8e12c2379af50252d21765e615f37\",\"filename\":\"docs/roadmap/code-index-v2/P8-TASK-PROFILE-DESCRIPTIVE.md\",\"status\":\"added\",\"additions\":110,\"deletions\":0,\"changes\":110,\"blob_url\":\"https://github.com/jyqj/codecortex/blob/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/docs%2Froadmap%2Fcode-index-v2%2FP8-TASK-PROFILE-DESCRIPTIVE.md\",\"raw_url\":\"https://github.com/jyqj/codecortex/raw/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/docs%2Froadmap%2Fcode-index-v2%2FP8-TASK-PROFILE-DESCRIPTIVE.md\",\"contents_url\":\"https://api.github.com/repos/jyqj/codecortex/contents/docs%2Froadmap%2Fcode-index-v2%2FP8-TASK-PROFILE-DESCRIPTIVE.md?ref=da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032\",\"patch\":\"@@ -0,0 +1,110 @@\\n+# P8 task profile descriptive population\\n+\\n+This separately registered population supplies descriptive P8-006 evidence. Its\\n+schema is `p8-profile-task-descriptive-v1` and native scope is\\n+`profile_task_descriptive_v1`. It has one observation per cell, with **45 cells\\n+and 85 retained records**. It is neither the sequential 150-shard study nor the\\n+1,350-cell `profile_isolated_v1` study. It changes no existing study, accepted\\n+sample, release condition, or task status.\\n+\\n+## Fixed population and history\\n+\\n+The eight mutation profiles are `no_op`, `body`, `api`, `config`, `batch_1`,\\n+`batch_10`, `batch_100`, and `batch_1000`. Each runs once at 1,000, 5,000, 10,000,\\n+50,000, and 100,000 generated source files. Each of these 40 cells creates fresh\\n+A/B inputs, retains its cold setup pair and full fifteen-table comparison,\\n+applies only its selected mutation, completes the original incremental closure,\\n+then performs its full control and full fifteen-table comparison. A batch cell\\n+starts with the fresh target-zero configuration; a config cell retains its\\n+independent target-one witness. The original fixture also reports its auxiliary\\n+visible configuration file separately from requested source-file capacity.\\n+\\n+The five additional cells use the original fanouts 1, 4, 16, 64, and 128. Their\\n+actual inputs contain **N+1 files**. Their `files: [1000]` plan field reserves\\n+capacity; it is not the fanout's measured file count. They retain the original\\n+initial full builds, initial fifteen-table comparison, mutation, dirty-budget\\n+closure, final full build/comparison, and independent call-edge assertions.\\n+First-build-incomplete remains an observation; aggregate success requires actual\\n+over-budget closure coverage in these original fanout results.\\n+\\n+The five cold-curve records are prescribed **before execution**: the setup from\\n+the `no_op` cell at each scale. They are a subset of the 40 setup records. The\\n+other 35 setups remain in full; none is selected or discarded according to time.\\n+The output counts 40 setups + 40 mutations + 5 fanouts = 85 records, not 90.\\n+\\n+Every cell uses seed `0xc0ffee`, N=1, shard index 0/count 1, main dirty budget\\n+200/resume limit 1024, and the independent fanout dirty budget 8/resume limit 128.\\n+The physical oracle remains `scale_capacity_v1`; all fifteen tables, canonical\\n+rows, duplicate semantics, limits and parity predicates stay unchanged. Each\\n+worker's five-hour deadline includes setup, mutation, closure, full control and\\n+parity. Its original native output budget is 512 MiB. Forty-five workers allow\\n+225 worker-hours in total; this is a distinct population and history, not an\\n+equivalent resharding of the existing studies. Actual runner scheduling may take\\n+longer than native time and is not a performance measurement.\\n+\\n+## Registration, source and original evidence\\n+\\n+The standalone build command performs one native release build. Before cells\\n+start, `build/task-registry.json` records all 45 exact plans and the actual\\n+source commit, source manifest, binary SHA-256/BLAKE3, native build receipt,\\n+observer manifest, run ID and attempt. `build/task-build.json` seals that registry\\n+and its complete file inventory. No placeholder identity is accepted at run or\\n+aggregate time. The observer closure includes this driver, the shared native\\n+driver/helper, runner capacity observer, this protocol and its document, the new\\n+capture wrapper and both tests, and the dedicated workflow.\\n+\\n+The build layout is `build/native-build/p8-scale`, with the unchanged original\\n+`native-build/build.json` and original source records. Each cell writes\\n+`task-shard.json`, `native-shard/shard.json`, and the original\\n+`native-shard/native/{plan.json,raw.jsonl,worker.stderr,worker-summary.json,report.json}`.\\n+The task receipt includes the exact build and registry digests. The native\\n+validator still verifies the original release producer, source before/after,\\n+binary, complete raw EOF, native and worker exits, closure, counts, full control,\\n+parity and independent witnesses. Failure never becomes an accepted prefix.\\n+\\n+The workflow attempts all 45 declared cells after a successful build, with\\n+`max-parallel: 10` and `fail-fast: false`. It retains every successful or failed\\n+cell's original output. Build failure starts no native cells and remains failure.\\n+The distinct `p8-task-*` artifact namespace includes run, attempt and cell\\n+identity. Bounded capture uploads preserve original byte ranges during execution;\\n+they report custody faults separately from native outcome. Prefixes do not\\n+replace complete shard receipts and cannot fill missing cells.\\n+\\n+The aggregator calls the original validators for the supplied files, records\\n+each input's success or exact failure, and retains all supplied original task\\n+receipts and file digests. It rejects missing, duplicate or extra cells, changed\\n+plans and mixed source, binary, driver, build, registry, run or attempt. It only\\n+sets `passed: true` when all 45 cells satisfy the original predicates. Missing\\n+or failed originals stay explicit in `task-matrix.json`; no old study or diagnostic\\n+sample may substitute for them. Preserve the original shard artifacts alongside\\n+the matrix, including failures.\\n+\\n+## Descriptive interpretation\\n+\\n+The matrix retains every raw timing, build and parity record, its original host\\n+and environment, and each available resource snapshot. It computes no pooled\\n+latency distribution, tail percentile, stable performance claim, speedup, causal\\n+cross-host comparison, or release certification. Nested elapsed measurements\\n+must not be added as disjoint costs. Missing resource peaks remain unknown;\\n+snapshot observations do not prove process-tree maxima. Vectors remain disabled\\n+or absent as recorded by the original protocol.\\n+\\n+Completion of this artifact is evidence for a later human task review. It does\\n+not edit `tasks.json`, waive dependencies or original task acceptance, certify\\n+P8-005, P8-008 or P8-020, or mark the N30 populations complete. All 45 results,\\n+including failures, must remain available regardless of the later review.\\n+\\n+## Commands\\n+\\n+Run only on the finally admitted fixed source with the actual workflow identity:\\n+\\n+```sh\\n+python3 scripts/p8_task_profile_matrix.py build --root . --output build --run-id RUN_ID --attempt ATTEMPT\\n+python3 scripts/p8_task_profile_matrix.py run --root . --build build --output cell --run-id RUN_ID --attempt ATTEMPT --scale 100000 --shard-index 0 --mutation-profile batch_10\\n+python3 scripts/p8_task_profile_matrix.py run --root . --build build --output fanout-cell --run-id RUN_ID --attempt ATTEMPT --scale 1000 --shard-index 0 --mutation-profile fanout --fanout 16\\n+python3 scripts/p8_task_profile_matrix.py aggregate --root . --build build --output aggregate --inputs CELL_DIRECTORIES\\n+```\\n+\\n+The workflow alone controls the full fixed matrix and its independent\\n+`p8-task-profile-run` label. These example commands do not authorize a local\\n+experiment or silently create a new registration.\"},{\"sha\":\"9a8e949aa7c0619f3bd92c6d0c72d3fde342890d\",\"filename\":\"docs/roadmap/code-index-v2/p8-profile-isolated-v1.json\",\"status\":\"added\",\"additions\":95,\"deletions\":0,\"changes\":95,\"blob_url\":\"https://github.com/jyqj/codecortex/blob/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/docs%2Froadmap%2Fcode-index-v2%2Fp8-profile-isolated-v1.json\",\"raw_url\":\"https://github.com/jyqj/codecortex/raw/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/docs%2Froadmap%2Fcode-index-v2%2Fp8-profile-isolated-v1.json\",\"contents_url\":\"https://api.github.com/repos/jyqj/codecortex/contents/docs%2Froadmap%2Fcode-index-v2%2Fp8-profile-isolated-v1.json?ref=da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032\",\"patch\":\"@@ -0,0 +1,95 @@\\n+{\\n+  \\\"schema\\\": \\\"p8-isolated-profile-study-v1\\\",\\n+  \\\"stage_scope\\\": \\\"profile_isolated_v1\\\",\\n+  \\\"registration_state\\\": \\\"candidate_not_executed\\\",\\n+  \\\"base_source_commit\\\": \\\"10ec828beb94200ec679302c45115760ebd55ee9\\\",\\n+  \\\"original_contract_inputs\\\": [\\n+    {\\n+      \\\"path\\\": \\\"docs/roadmap/code-index-v2/tasks.json\\\",\\n+      \\\"git_blob_sha1\\\": \\\"959a25ba851ff88f286bab0fa14167878129b1dd\\\",\\n+      \\\"sha256\\\": \\\"d51f61a920d887d375e95ca529509d0750233ea22477e40f7d43b3caa985c495\\\"\\n+    },\\n+    {\\n+      \\\"path\\\": \\\"docs/roadmap/code-index-v2/09-BENCHMARK.md\\\",\\n+      \\\"git_blob_sha1\\\": \\\"5ced0c455e7e774a9d95da23187c64dcefc37314\\\",\\n+      \\\"sha256\\\": \\\"0c8bcbed17ea4e83b1dc55e9828f93a27e2a334a0d0eaa056302944260d0a731\\\"\\n+    },\\n+    {\\n+      \\\"path\\\": \\\"docs/roadmap/code-index-v2/P8-SCALE.md\\\",\\n+      \\\"git_blob_sha1\\\": \\\"d23c80666c8885ee7274cdffc3c023e6a0ef9e08\\\",\\n+      \\\"sha256\\\": \\\"7093bcdb74a7bcd6ff32e05f5cd2c7a7bd6576c90fff42b36251884cfbfe1442\\\"\\n+    }\\n+  ],\\n+  \\\"task\\\": \\\"P8-006\\\",\\n+  \\\"run_binding\\\": \\\"actual future source+binary+driver manifest+run_id+run_attempt; all fixed before samples\\\",\\n+  \\\"mutation_profiles\\\": [\\n+    \\\"no_op\\\",\\n+    \\\"body\\\",\\n+    \\\"api\\\",\\n+    \\\"config\\\",\\n+    \\\"batch_1\\\",\\n+    \\\"batch_10\\\",\\n+    \\\"batch_100\\\",\\n+    \\\"batch_1000\\\"\\n+  ],\\n+  \\\"scales\\\": [\\n+    1000,\\n+    5000,\\n+    10000,\\n+    50000,\\n+    100000\\n+  ],\\n+  \\\"fanouts\\\": [\\n+    1,\\n+    4,\\n+    16,\\n+    64,\\n+    128\\n+  ],\\n+  \\\"fanout_actual_files\\\": \\\"fanout+1; files=1000 is only original capacity-reservation transport field\\\",\\n+  \\\"repetitions\\\": 30,\\n+  \\\"mutation_slots\\\": 1200,\\n+  \\\"fanout_slots\\\": 150,\\n+  \\\"setup_pairs_separately_retained\\\": 1200,\\n+  \\\"seed\\\": 12648430,\\n+  \\\"worker_deadline_ms\\\": 18000000,\\n+  \\\"worker_max_output_bytes\\\": 536870912,\\n+  \\\"main_dirty_budget\\\": 200,\\n+  \\\"main_max_resume_builds\\\": 1024,\\n+  \\\"fanout_dirty_budget\\\": 8,\\n+  \\\"fanout_max_resume_builds\\\": 128,\\n+  \\\"max_parallel\\\": 10,\\n+  \\\"job_timeout_minutes\\\": 350,\\n+  \\\"total_allowance_worker_hours\\\": 6750,\\n+  \\\"old_full_study_allowance_worker_hours\\\": 750,\\n+  \\\"budget_difference\\\": \\\"9x aggregate worker time allowance, not equivalent re-sharding of scale_capacity_v1; each worker still includes all setup and parity under original 5h\\\",\\n+  \\\"history_difference\\\": \\\"independent fresh A/B per selected profile, not the original sequential warm/history distribution; OS page cache retained\\\",\\n+  \\\"main_cell\\\": [\\n+    \\\"fresh A/B generate same seed and original config augmentation\\\",\\n+    \\\"two full builds with no parse errors\\\",\\n+    \\\"initial complete 15-table parity and target0 config witness\\\",\\n+    \\\"one registered mutation applied to both trees\\\",\\n+    \\\"incremental + up to1024 resumes preserving partial status\\\",\\n+    \\\"actual full-control rebuild\\\",\\n+    \\\"final complete 15-table parity and config witness target1 only for config, target0 for all other fresh profiles\\\"\\n+  ],\\n+  \\\"fanout_cell\\\": [\\n+    \\\"original actual N+1 input/independent call-edge assertions\\\",\\n+    \\\"two original full builds and initial15-table canonical comparison with original reports retained\\\",\\n+    \\\"original API mutation plus dirty8/resume128\\\",\\n+    \\\"actual full rebuild and final15-table canonical comparison\\\",\\n+    \\\"actual first-build-incomplete observation retained; aggregate requires original over-budget coverage\\\"\\n+  ],\\n+  \\\"negative_cases\\\": [\\n+    \\\"missing/duplicate/extra slot\\\",\\n+    \\\"mixed source/binary/driver/build/run/attempt\\\",\\n+    \\\"old full/cold scope or failed prefix reuse\\\",\\n+    \\\"changed workload/budget or missing original tables/counts/reports\\\",\\n+    \\\"incomplete native terminal or closure\\\",\\n+    \\\"failed or truncated original evidence\\\"\\n+  ],\\n+  \\\"task_statuses_changed\\\": false,\\n+  \\\"release_certification\\\": \\\"not_run\\\",\\n+  \\\"prior_studies_unchanged\\\": true,\\n+  \\\"original_registration_parent\\\": \\\"044c008c9459cfa61e7701db2eb868342c508a39\\\"\\n+}\"},{\"sha\":\"f51e04538e30dd8fa3c2b585c2fd166bf7855273\",\"filename\":\"docs/roadmap/code-index-v2/p8-profile-task-descriptive-v1.json\",\"status\":\"added\",\"additions\":47,\"deletions\":0,\"changes\":47,\"blob_url\":\"https://github.com/jyqj/codecortex/blob/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/docs%2Froadmap%2Fcode-index-v2%2Fp8-profile-task-descriptive-v1.json\",\"raw_url\":\"https://github.com/jyqj/codecortex/raw/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/docs%2Froadmap%2Fcode-index-v2%2Fp8-profile-task-descriptive-v1.json\",\"contents_url\":\"https://api.github.com/repos/jyqj/codecortex/contents/docs%2Froadmap%2Fcode-index-v2%2Fp8-profile-task-descriptive-v1.json?ref=da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032\",\"patch\":\"@@ -0,0 +1,47 @@\\n+{\\n+  \\\"schema\\\": \\\"p8-profile-task-descriptive-v1\\\",\\n+  \\\"stage_scope\\\": \\\"profile_task_descriptive_v1\\\",\\n+  \\\"registration_state\\\": \\\"source_protocol_only_runtime_identity_required\\\",\\n+  \\\"actual_source_commit\\\": null,\\n+  \\\"actual_build\\\": null,\\n+  \\\"actual_run_id\\\": null,\\n+  \\\"actual_run_attempt\\\": null,\\n+  \\\"runtime_registration\\\": \\\"build/task-registry.json sealed before any cell; exact source, binary, observer, native build receipt, run and attempt\\\",\\n+  \\\"mutation_profiles\\\": [\\\"no_op\\\", \\\"body\\\", \\\"api\\\", \\\"config\\\", \\\"batch_1\\\", \\\"batch_10\\\", \\\"batch_100\\\", \\\"batch_1000\\\"],\\n+  \\\"scales\\\": [1000, 5000, 10000, 50000, 100000],\\n+  \\\"fanouts\\\": [1, 4, 16, 64, 128],\\n+  \\\"fanout_actual_files\\\": \\\"N+1; files1000 is the capacity-reservation field only\\\",\\n+  \\\"repetitions\\\": 1,\\n+  \\\"shard_count\\\": 1,\\n+  \\\"shard_index\\\": 0,\\n+  \\\"cell_count\\\": 45,\\n+  \\\"record_count\\\": 85,\\n+  \\\"setup_pair_count\\\": 40,\\n+  \\\"mutation_record_count\\\": 40,\\n+  \\\"fanout_record_count\\\": 5,\\n+  \\\"cold_curve_preselected_profile\\\": \\\"no_op\\\",\\n+  \\\"cold_curve_count\\\": 5,\\n+  \\\"cold_curve_is_subset_of_setup\\\": true,\\n+  \\\"other_35_setup_records_retained\\\": true,\\n+  \\\"seed\\\": 12648430,\\n+  \\\"worker_deadline_ms\\\": 18000000,\\n+  \\\"worker_max_output_bytes\\\": 536870912,\\n+  \\\"main_dirty_budget\\\": 200,\\n+  \\\"main_max_resume_builds\\\": 1024,\\n+  \\\"fanout_dirty_budget\\\": 8,\\n+  \\\"fanout_max_resume_builds\\\": 128,\\n+  \\\"oracle_capacity_profile\\\": \\\"scale_capacity_v1\\\",\\n+  \\\"full_parity_tables\\\": 15,\\n+  \\\"max_parallel\\\": 10,\\n+  \\\"fail_fast\\\": false,\\n+  \\\"aggregate_worker_allowance_hours\\\": 225,\\n+  \\\"history\\\": \\\"fresh pristine A/B per cell; setup and full controls included in original deadline\\\",\\n+  \\\"positive_acceptance\\\": [\\\"all45 exact unique registered cells\\\", \\\"same source/binary/driver/build/run/attempt/registry\\\", \\\"original complete raw EOF and native worker success\\\", \\\"complete closure and full fifteen-table parity\\\", \\\"original independent witnesses and actual fanout over-budget coverage\\\"],\\n+  \\\"negative_acceptance\\\": [\\\"missing/duplicate/extra cell\\\", \\\"mixed identity or changed plan\\\", \\\"failed or truncated native result\\\", \\\"missing full control/parity/table/count/witness\\\", \\\"old population or captured prefix substitution\\\"],\\n+  \\\"failed_originals\\\": \\\"retain every attempted cell, full task receipt, original files and failure; aggregate false for any missing or failed cell\\\",\\n+  \\\"statistics\\\": \\\"N1 descriptive only; no pooled latency, tail percentile or stable performance claim\\\",\\n+  \\\"capture_credit\\\": \\\"custody only; uploaded prefix is not native success or a complete cell\\\",\\n+  \\\"task_statuses_changed\\\": false,\\n+  \\\"release_certification\\\": \\\"not_run\\\",\\n+  \\\"prior_studies_unchanged\\\": true\\n+}\"},{\"sha\":\"88d05e7c1a51ca5fba78cd3ec5d28df8fbd6bbad\",\"filename\":\"scripts/p8_profile_matrix.py\",\"status\":\"added\",\"additions\":404,\"deletions\":0,\"changes\":404,\"blob_url\":\"https://github.com/jyqj/codecortex/blob/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/scripts%2Fp8_profile_matrix.py\",\"raw_url\":\"https://github.com/jyqj/codecortex/raw/da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032/scripts%2Fp8_profile_matrix.py\",\"contents_url\":\"https://api.github.com/repos/jyqj/codecortex/contents/scripts%2Fp8_profile_matrix.py?ref=da4584aebf2bba1b4b0a53a93ac2f9ae8f9de032\",\"patch\":\"@@ -0,0 +1,404 @@\\n+#!/usr/bin/env python3\\n+\\\"\\\"\\\"Separate fresh-history P8-006 study: 1200 mutation + 150 actual N+1 fanout cells.\\n+\\n+Every worker includes setup under its original five-hour deadline. The increased\\n+whole-study allowance and fresh history are explicitly different from the old\\n+sequential all-stage study; no failed prefix or prior source can contribute N.\\n+\\\"\\\"\\\"\\n+import argparse\\n+from collections import defaultdict\\n+import hashlib\\n+import json\\n+import os\\n+from pathlib import Path\\n+import subprocess\\n+import sys\\n+\\n+import p8_scale_matrix as full\\n+from p7_build_identity import file_sha256, json_bytes\\n+\\n+SCHEMA = \\\"p8-isolated-profile-study-v1\\\"\\n+SCOPE = \\\"profile_isolated_v1\\\"\\n+DRIVER_FILES = full.DRIVER_FILES + (\\n+    \\\"scripts/p8_profile_matrix.py\\\", \\\"scripts/p8_runner_capacity.py\\\",\\n+    \\\".github/workflows/p8-profile.yml\\\",\\n+    \\\"docs/roadmap/code-index-v2/P8-PROFILE-ISOLATED.md\\\",\\n+    \\\"docs/roadmap/code-index-v2/p8-profile-isolated-v1.json\\\",\\n+)\\n+require = full.require\\n+ERRORS = (OSError, ValueError, KeyError, TypeError, subprocess.SubprocessError)\\n+ENVIRONMENT_KEYS = (\\\"CODECORTEX_SEED_CACHE_MAX_SYMBOLS\\\", \\\"RUSTFLAGS\\\",\\n+                    \\\"CARGO_ENCODED_RUSTFLAGS\\\", \\\"TMPDIR\\\", \\\"TMP\\\", \\\"TEMP\\\")\\n+\\n+\\n+def driver_snapshot(root):\\n+    root = Path(root).resolve(strict=True)\\n+    old = full.driver_snapshot(root)\\n+    require(Path(__file__).resolve() == root / \\\"scripts/p8_profile_matrix.py\\\",\\n+            \\\"profile observer loaded from another checkout\\\")\\n+    inputs = dict(old[\\\"inputs\\\"])\\n+    for relative in DRIVER_FILES[len(full.DRIVER_FILES):]:\\n+        path = root / relative\\n+        require(path.is_file() and not path.is_symlink(), \\\"nonregular profile observer input\\\")\\n+        committed = subprocess.check_output([\\\"git\\\", \\\"show\\\", old[\\\"source_commit\\\"] + \\\":\\\" + relative], cwd=root)\\n+        require(file_sha256(path) == hashlib.sha256(committed).hexdigest(), \\\"profile observer source drift: \\\" + relative)\\n+        inputs[relative] = file_sha256(path)\\n+    require(subprocess.check_output([\\\"git\\\", \\\"rev-parse\\\", \\\"HEAD\\\"], cwd=root, text=True).strip() == old[\\\"source_commit\\\"],\\n+            \\\"profile observer HEAD changed\\\")\\n+    return dict(source_commit=old[\\\"source_commit\\\"], inputs=inputs,\\n+                manifest_sha256=hashlib.sha256(json_bytes(inputs)).hexdigest())\\n+\\n+\\n+def study_identity(run_id, attempt):\\n+    require(isinstance(run_id, str) and run_id.isascii() and run_id.isdecimal() and 0 < int(run_id) < 2 ** 64,\\n+            \\\"a positive official workflow run ID is required\\\")\\n+    full.integer(attempt, \\\"run attempt\\\", 1, 2 ** 32 - 1)\\n+    return dict(protocol=SCHEMA, run_id=run_id, run_attempt=attempt)\\n+\\n+\\n+PROFILES = (\\\"no_op\\\", \\\"body\\\", \\\"api\\\", \\\"config\\\", \\\"batch_1\\\", \\\"batch_10\\\", \\\"batch_100\\\", \\\"batch_1000\\\")\\n+\\n+\\n+def registered_plan(scale, shard_index, shard_count=30, repetitions=30, seed=12648430,\\n+                    deadline_ms=18_000_000, capacity_profile=full.CAPACITY_PROFILE, *, study,\\n+                    mutation_profile, fanout=None):\\n+    require(type(repetitions) is int and repetitions == 30 and type(shard_count) is int and shard_count == 30\\n+            and seed == 12648430 and deadline_ms == 18_000_000 and capacity_profile == full.CAPACITY_PROFILE,\\n+            \\\"isolated profile population/seed/worker budget/capacity differs\\\")\\n+    require(mutation_profile in PROFILES + (\\\"fanout\\\",), \\\"unknown isolated profile\\\")\\n+    if mutation_profile == \\\"fanout\\\":\\n+        require(type(fanout) is int and fanout in full.FANOUTS and type(scale) is int and scale == 1000,\\n+                \\\"fanout requires its actual N+1 fixture and the fixed 1000 capacity-reservation field\\\")\\n+    else:\\n+        require(fanout is None, \\\"mutation cell cannot carry a fanout\\\")\\n+    require(full.exact_equal(study, study_identity(study[\\\"run_id\\\"], study[\\\"run_attempt\\\"])), \\\"profile study identity differs\\\")\\n+    plan = full.registered_plan(scale, shard_index, shard_count, repetitions, seed, deadline_ms, capacity_profile)\\n+    plan.update(stage_scope=SCOPE, skip_fanout=mutation_profile != \\\"fanout\\\",\\n+                profile_study=dict(run_id=study[\\\"run_id\\\"], run_attempt=study[\\\"run_attempt\\\"],\\n+                                   mutation_profile=mutation_profile, fanout=fanout))\\n+    return plan\\n+\\n+\\n+def envelope(out, kind, study, driver):\\n+    return dict(schema=SCHEMA, kind=kind, stage_scope=SCOPE, study=study,\\n+                driver_source=driver, started_utc=full.utc(), status=\\\"failed\\\", passed=False,\\n+                release_certification=\\\"not_run\\\", task_statuses_changed=False)\\n+\\n+\\n+def finish(out, filename, record):\\n+    record[\\\"finished_utc\\\"] = full.utc()\\n+    record[\\\"files\\\"] = full.inventory(out)\\n+    full.write_new(out / filename, record)\\n+    return record\\n+\\n+\\n+def verify_envelope(directory, filename, kind, root):\\n+    record = full.read_json(directory / filename)\\n+    require(record.get(\\\"schema\\\") == SCHEMA and record.get(\\\"kind\\\") == kind and record.get(\\\"stage_scope\\\") == SCOPE\\n+            and record.get(\\\"status\\\") == \\\"passed\\\" and record.get(\\\"passed\\\") is True,\\n+            \\\"profile \\\" + kind + \\\" failed or belongs to another protocol\\\")\\n+    study = record[\\\"study\\\"]\\n+    require(full.exact_equal(study, study_identity(study[\\\"run_id\\\"], study[\\\"run_attempt\\\"])), \\\"study identity differs\\\")\\n+    require(record.get(\\\"driver_source\\\") == driver_snapshot(root), \\\"profile observer identity differs\\\")\\n+    require(record.get(\\\"files\\\") == full.inventory(directory, (filename,)), \\\"profile envelope inventory changed\\\")\\n+    return record\\n+\\n+\\n+def build(root, output, run_id, attempt, target_directory=None):\\n+    root = Path(root).resolve(strict=True)\\n+    out = full.new_directory(output)\\n+    record = envelope(out, \\\"profile-build\\\", study_identity(run_id, attempt), driver_snapshot(root))\\n+    try:\\n+        native = full.build(root, out / \\\"native-build\\\", target_directory or out.parent / (out.name + \\\"-cargo\\\"))\\n+        require(native[\\\"status\\\"] == \\\"passed\\\", \\\"native release build failed\\\")\\n+        require(record[\\\"driver_source\\\"] == driver_snapshot(root), \\\"profile build observer changed\\\")\\n+        record.update(status=\\\"passed\\\", passed=True, source_commit=native[\\\"source_commit\\\"],\\n+                      source_manifest_sha256=native[\\\"source_manifest_sha256\\\"],\\n+                      binary_sha256=native[\\\"binary_sha256\\\"], binary_blake3=native[\\\"binary_blake3\\\"],\\n+                      native_build_receipt_sha256=file_sha256(out / \\\"native-build/build.json\\\"))\\n+    except ERRORS as error:\\n+        record[\\\"error\\\"] = str(error)\\n+    return finish(out, \\\"profile-build.json\\\", record)\\n+\\n+\\n+def validate_build(directory, root=None):\\n+    root = Path(root or Path(__file__).resolve().parents[1]).resolve(strict=True)\\n+    directory = Path(directory).resolve(strict=True)\\n+    outer = verify_envelope(directory, \\\"profile-build.json\\\", \\\"profile-build\\\", root)\\n+    built, binary = full.validate_build(directory / \\\"native-build\\\", root)\\n+    require(outer[\\\"native_build_receipt_sha256\\\"] == file_sha256(directory / \\\"native-build/build.json\\\"),\\n+            \\\"profile build inner receipt differs\\\")\\n+    for key in (\\\"source_commit\\\", \\\"source_manifest_sha256\\\", \\\"binary_sha256\\\", \\\"binary_blake3\\\"):\\n+        require(outer[key] == built[key], \\\"profile build \\\" + key + \\\" differs\\\")\\n+    return outer, built, binary\\n+\\n+\\n+def observed_environment(temporary_root):\\n+    result = {key: os.environ.get(key) for key in ENVIRONMENT_KEYS}\\n+    result.update({key: str(temporary_root) for key in (\\\"TMPDIR\\\", \\\"TMP\\\", \\\"TEMP\\\")})\\n+    return result\\n+\\n+\\n+def run_shard(root, build_directory, output, scale, shard_index, run_id, attempt, mutation_profile, fanout=None):\\n+    root = Path(root).resolve(strict=True)\\n+    study = study_identity(run_id, attempt)\\n+    built, _, _ = validate_build(build_directory, root)\\n+    require(built[\\\"study\\\"] == study, \\\"build belongs to another study/run/attempt\\\")\\n+    out = full.new_directory(output)\\n+    record = envelope(out, \\\"profile-shard\\\", study, driver_snapshot(root))\\n+    record[\\\"profile_build_receipt_sha256\\\"] = file_sha256(Path(build_directory) / \\\"profile-build.json\\\")\\n+    record[\\\"measurement_environment\\\"] = observed_environment(out)\\n+    try:\\n+        inner = full.run_shard(root, Path(build_directory) / \\\"native-build\\\", out / \\\"native-shard\\\",\\n+                               registered_plan(scale, shard_index, study=study, mutation_profile=mutation_profile, fanout=fanout))\\n+        require(inner[\\\"status\\\"] == \\\"passed\\\", \\\"native profile shard failed\\\")\\n+        require(record[\\\"driver_source\\\"] == driver_snapshot(root), \\\"profile observer changed during measurement\\\")\\n+        require(record[\\\"measurement_environment\\\"] == observed_environment(out), \\\"measurement environment changed\\\")\\n+        record.update(status=\\\"passed\\\", passed=True)\\n+    except ERRORS as error:\\n+        record[\\\"error\\\"] = str(error)\\n+    return finish(out, \\\"profile-shard.json\\\", record)\\n+\\n+\\n+def expected_fanout_case(n, seed):\\n+    initial = {\\\"api.ts\\\": \\\"export function scale_ping(x:number):number{return x;}\\\\n\\\"}\\n+    assertions = []\\n+    for i in range(n):\\n+        path = f\\\"use_{i:03}.ts\\\"\\n+        initial[path] = (\\\"import {scale_ping} from './api';\\\\n\\\"\\n+                         f\\\"export function run_{i}(x:number):number{{return scale_ping(x);}}\\\\n\\\")\\n+        assertions.append(dict(id=f\\\"caller_{i}\\\", table=\\\"call_edges\\\", count=1,\\n+            matches=dict(file_path=path, callee_symbol=\\\"scale_ping\\\", target_file_path=\\\"api.ts\\\")))\\n+    return dict(schema_version=1, name=f\\\"p8-fanout-{n}-{seed}\\\", initial=initial,\\n+        stages=[dict(mutation=dict(kind=\\\"write\\\", path=\\\"api.ts\\\", content=\\n+            f\\\"export function scale_ping(x:number,offset:number={seed % 1000 + 1}):number{{return x+offset;}}\\\\n\\\"),\\n+            reopen=False, settle=True, assertions=assertions)], dirty_budget=8, max_resume_builds=128)\\n+\\n+\\n+def inspect_raw(path, plan):\\n+    selection = plan[\\\"profile_study\\\"]\\n+    profile = selection[\\\"mutation_profile\\\"]\\n+    inspected = full._inspect_raw(path, plan, isolated_profile=profile)\\n+    snapshots = {}\\n+    with Path(path).open(\\\"rb\\\") as stream:\\n+        for line in stream:\\n+            event = full.decode(line)\\n+            if event[\\\"event\\\"] == \\\"run_started\\\":\\n+                inspected[\\\"profile_environment\\\"] = event[\\\"profile_environment\\\"]\\n+            elif event[\\\"event\\\"] == \\\"build_finished\\\":\\n+                require(\\\"process_snapshot\\\" in event and isinstance(event.get(\\\"resource_scope\\\"), str),\\n+                        \\\"original worker resource observation missing\\\")\\n+                snapshots[event[\\\"label\\\"]] = dict(process_snapshot=event[\\\"process_snapshot\\\"],\\n+                                                 resource_scope=event[\\\"resource_scope\\\"])\\n+            elif event[\\\"event\\\"] == \\\"fanout_started\\\":\\n+                require(full.exact_equal(event[\\\"case\\\"], expected_fanout_case(selection[\\\"fanout\\\"], plan[\\\"seed\\\"])),\\n+                        \\\"registered fanout fixture/mutation/independent witnesses differ\\\")\\n+            elif event[\\\"event\\\"] == \\\"fanout_finished\\\":\\n+                initial = event[\\\"result\\\"].get(\\\"initial_evidence\\\", {})\\n+                require(initial.get(\\\"equal\\\") is True and set(initial.get(\\\"tables\\\", [])) == full.TABLES\\n+                        and len(initial[\\\"tables\\\"]) == 15\\n+                        and set(initial.get(\\\"incremental\\\", {})) == set(initial.get(\\\"full\\\", {})) == full.TABLES\\n+                        and full.exact_equal(initial[\\\"incremental\\\"], initial[\\\"full\\\"]),\\n+                        \\\"fanout initial full fifteen-table parity missing\\\")\\n+                require(len(initial[\\\"incremental\\\"][\\\"files\\\"]) == selection[\\\"fanout\\\"] + 1,\\n+                        \\\"fanout initial indexed file count differs from actual N+1\\\")\\n+                initial_reports = [full.check_build_report(initial.get(key))\\n+                                   for key in (\\\"incremental_report\\\", \\\"full_report\\\")]\\n+                point = event[\\\"result\\\"][\\\"checkpoints\\\"][0]\\n+                final_full = full.check_build_report(point.get(\\\"full_report\\\"))\\n+                require(all(item[\\\"complete\\\"] and item[\\\"build_timing\\\"][\\\"full_staging_us\\\"] is not None\\n+                            for item in initial_reports + [final_full]), \\\"fanout full build incomplete or not full\\\")\\n+                require(initial.get(\\\"runtime_config\\\") == {\\\"auto_index\\\":{\\\"enabled\\\":False},\\n+                        \\\"indexing\\\":{\\\"dirty_propagation_max_files\\\":8,\\\"db_read_pool_size\\\":1}},\\n+                        \\\"fanout original runtime config differs\\\")\\n+                require(\\\"process_snapshot\\\" in initial and \\\"process_snapshot\\\" in point\\n+                        and isinstance(initial.get(\\\"resource_scope\\\"), str), \\\"fanout resource observations missing\\\")\\n+                sample = inspected[\\\"measurements\\\"][0]\\n+                sample[\\\"initial_evidence\\\"] = initial\\n+                sample[\\\"full_control_build_timing\\\"] = full.sum_build_timing([final_full])\\n+                sample[\\\"full_control_ms\\\"] = final_full[\\\"elapsed_ms\\\"]\\n+                sample[\\\"process_snapshot\\\"] = point[\\\"process_snapshot\\\"]\\n+    expected = 1 if profile == \\\"fanout\\\" else 2\\n+    require(len(inspected[\\\"measurements\\\"]) == expected, \\\"isolated native sample count differs\\\")\\n+    if profile != \\\"fanout\\\":\\n+        require(len(snapshots) >= 4, \\\"missing fresh setup, incremental or final full resource observation\\\")\\n+        inspected[\\\"resource_snapshots\\\"] = snapshots\\n+    return inspected\\n+\\n+\\n+def validate_shard(directory, outer_build, built, binary, build_directory, root=None):\\n+    root = Path(root or Path(__file__).resolve().parents[1]).resolve(strict=True)\\n+    directory = Path(directory).resolve(strict=True)\\n+    record = verify_envelope(directory, \\\"profile-shard.json\\\", \\\"profile-shard\\\", root)\\n+    require(record[\\\"study\\\"] == outer_build[\\\"study\\\"] and record[\\\"driver_source\\\"] == outer_build[\\\"driver_source\\\"],\\n+            \\\"profile shard belongs to another study/observer\\\")\\n+    require(record[\\\"profile_build_receipt_sha256\\\"] == file_sha256(Path(build_directory) / \\\"profile-build.json\\\"),\\n+            \\\"profile shard used another outer build\\\")\\n+    selection = full.read_json(directory / \\\"native-shard/registered-plan.json\\\")[\\\"profile_study\\\"]\\n+    inspected = full._validate_shard(directory / \\\"native-shard\\\", built, binary,\\n+        file_sha256(Path(build_directory) / \\\"native-build/build.json\\\"),\\n+        protocol_plan=lambda *args: registered_plan(*args, study=record[\\\"study\\\"],\\n+            mutation_profile=selection[\\\"mutation_profile\\\"], fanout=selection[\\\"fanout\\\"]), raw_inspector=inspect_raw)\\n+    summary = full.read_json(directory / \\\"native-shard/native/worker-summary.json\\\")\\n+    require(summary.get(\\\"stage_scope\\\") == SCOPE and summary.get(\\\"sample_count\\\") == (1 if selection[\\\"mutation_profile\\\"] == \\\"fanout\\\" else 2), \\\"native profile terminal summary differs\\\")\\n+    measured = inspected[\\\"profile_environment\\\"]\\n+    seed = measured[\\\"seed_cache_max_symbols\\\"]\\n+    full.integer(seed.get(\\\"effective\\\"), \\\"effective seed cache capacity\\\")\\n+    parsed = seed.get(\\\"parsed_usize\\\")\\n+    require(parsed is None or type(parsed) is int and parsed >= 0, \\\"invalid native seed cap parse result\\\")\\n+    require(seed[\\\"effective\\\"] == (500_000 if parsed is None else parsed), \\\"seed cache effective capacity differs\\\")\\n+    environment = record[\\\"measurement_environment\\\"]\\n+    require(set(environment) == set(ENVIRONMENT_KEYS), \\\"profile environment keys differ\\\")\\n+    require(seed.get(\\\"raw\\\") == environment[\\\"CODECORTEX_SEED_CACHE_MAX_SYMBOLS\\\"] and\\n+            seed.get(\\\"read_status\\\") == (\\\"absent\\\" if seed[\\\"raw\\\"] is None else \\\"unicode\\\"),\\n+            \\\"worker seed cache environment differs\\\")\\n+    report = full.read_json(directory / \\\"native-shard/native/report.json\\\")\\n+    temporary = report.get(\\\"profile_temporary_environment\\\", {})\\n+    parent = full.producer_path(temporary.get(\\\"parent_root\\\"), \\\"supervisor temporary root\\\")\\n+    worker = full.producer_path(temporary.get(\\\"worker_root\\\"), \\\"worker temporary root\\\")\\n+    require(worker.parent == parent and str(parent) == environment[\\\"TMPDIR\\\"],\\n+            \\\"worker temporary root is not the supervisor-owned child on the registered filesystem\\\")\\n+    worker_environment = {key: environment[key] for key in ENVIRONMENT_KEYS[1:]}\\n+    worker_environment.update({key: str(worker) for key in (\\\"TMPDIR\\\", \\\"TMP\\\", \\\"TEMP\\\")})\\n+    require(measured.get(\\\"runtime_environment\\\") == worker_environment, \\\"worker runtime environment differs\\\")\\n+    inner = full.read_json(directory / \\\"native-shard/shard.json\\\")\\n+    require({key: environment[key] for key in (\\\"TMPDIR\\\", \\\"TMP\\\", \\\"TEMP\\\")} == inner[\\\"temporary_environment\\\"],\\n+            \\\"profile temporary filesystem differs from capacity preflight\\\")\\n+    return inspected | dict(directory=str(directory), receipt_sha256=file_sha256(directory / \\\"profile-shard.json\\\"),\\n+                            study=record[\\\"study\\\"], driver_source=record[\\\"driver_source\\\"],\\n+                            build_receipt_sha256=record[\\\"profile_build_receipt_sha256\\\"],\\n+                            measurement_environment=environment)\\n+\\n+\\n+def slot_key(plan):\\n+    selection = plan[\\\"profile_study\\\"]\\n+    return (selection[\\\"mutation_profile\\\"], selection[\\\"fanout\\\"] if selection[\\\"mutation_profile\\\"] == \\\"fanout\\\"\\n+            else plan[\\\"files\\\"][0], plan[\\\"shard\\\"][\\\"index\\\"])\\n+\\n+\\n+def expected_slots():\\n+    return ({(profile, scale, index) for profile in PROFILES for scale in full.SCALES for index in range(30)}\\n+            | {(\\\"fanout\\\", fanout, index) for fanout in full.FANOUTS for index in range(30)})\\n+\\n+\\n+def combine(shards):\\n+    expected = expected_slots()\\n+    seen, groups, identities, environments, inputs, setup = set(), defaultdict(list), set(), {}, {}, []\\n+    for shard in shards:\\n+        plan = shard[\\\"plan\\\"]\\n+        key = slot_key(plan)\\n+        require(key in expected and key not in seen, \\\"duplicate/unexpected isolated slot\\\")\\n+        fanout = key[0] == \\\"fanout\\\"\\n+        require(full.exact_equal(plan, registered_plan(plan[\\\"files\\\"][0], key[2], study=shard[\\\"study\\\"],\\n+            mutation_profile=key[0], fanout=key[1] if fanout else None)), \\\"isolated registered plan differs\\\")\\n+        seen.add(key)\\n+        engine = shard[\\\"engine\\\"]\\n+        identity = {field: engine.get(field) for field in (\\\"engine_head_observed\\\", \\\"source_files_digest\\\", \\\"cargo_lock_digest\\\",\\n+                    \\\"binary_digest\\\", \\\"eval_version\\\", \\\"os\\\", \\\"arch\\\", \\\"rustflags\\\", \\\"eval_debug_assertions\\\")}\\n+        identity.update(study=shard[\\\"study\\\"], driver_source=shard[\\\"driver_source\\\"],\\n+                        build_receipt_sha256=shard[\\\"build_receipt_sha256\\\"])\\n+        identities.add(json.dumps(identity, sort_keys=True))\\n+        require(len(shard[\\\"measurements\\\"]) == (1 if fanout else 2), \\\"missing setup or selected profile\\\")\\n+        sample = shard[\\\"measurements\\\"][-1]\\n+        group = f\\\"fanout-{key[1]}\\\" if fanout else f\\\"scale-{key[1]}/{key[0]}\\\"\\n+        sample_id = f\\\"fanout-{key[1]}/repetition-{key[2]}\\\" if fanout else f\\\"scale-{key[1]}/repetition-{key[2]}\\\"\\n+        require(sample[\\\"group\\\"] == group and sample[\\\"sample\\\"] == sample_id, \\\"profile sample identity differs\\\")\\n+        if not fanout:\\n+            cold = shard[\\\"measurements\\\"][0]\\n+            require(cold[\\\"group\\\"] == f\\\"scale-{key[1]}/cold\\\" and cold[\\\"sample\\\"] == sample_id,\\n+                    \\\"missing pristine setup pair\\\")\\n+            setup.append(dict(slot=list(key), sample=cold, resource_snapshots=shard[\\\"resource_snapshots\\\"]))\\n+        environment = dict(shard[\\\"environment\\\"], engine_cpu_parallelism=engine.get(\\\"cpu_parallelism\\\"),\\n+                           measurement_environment=shard[\\\"measurement_environment\\\"],\\n+                           profile_environment=shard[\\\"profile_environment\\\"])\\n+        require(isinstance(environment.get(\\\"host\\\"), str) and environment[\\\"host\\\"], \\\"missing measured host\\\")\\n+        full.integer(environment[\\\"engine_cpu_parallelism\\\"], \\\"native CPU parallelism\\\", 1)\\n+        environment_id = hashlib.sha256(json_bytes(environment)).hexdigest()\\n+        environments[environment_id] = environment\\n+        input_key = f\\\"fanout-{key[1]}\\\" if fanout else f\\\"scale-{key[1]}\\\"\\n+        if input_key in inputs:\\n+            require(inputs[input_key] == shard[\\\"input_digest\\\"], \\\"pristine corpus differs across profiles/repetitions\\\")\\n+        inputs[input_key] = shard[\\\"input_digest\\\"]\\n+        groups[group].append(sample | dict(environment_id=environment_id))\\n+    require(seen == expected and len(identities) == 1, \\\"missing isolated slots or mixed source/binary/study\\\")\\n+    results = []\\n+    for name, samples in sorted(groups.items()):\\n+        require(len(samples) == 30, \\\"profile group must retain all N30\\\")\\n+        strata = defaultdict(list)\\n+        samples.sort(key=lambda sample: int(sample[\\\"sample\\\"].rsplit(\\\"-\\\", 1)[1]))\\n+        for sample in samples:\\n+            strata[sample[\\\"environment_id\\\"]].append(sample)\\n+        results.append(dict(group=name, n=30, samples=samples,\\n+            environment_strata=[dict(environment_id=identity, **full.summarize_group(name, values))\\n+                                for identity, values in sorted(strata.items())],\\n+            pooled_latency_statistics=\\\"not_computed_heterogeneous_coverage\\\"))\\n+    require(any(sample.get(\\\"first_build_incomplete\\\") is True for name, samples in groups.items()\\n+                if name.startswith(\\\"fanout-\\\") for sample in samples), \\\"no actual over-budget closure observed\\\")\\n+    return dict(schema=SCHEMA, stage_scope=SCOPE, status=\\\"complete_isolated_profile_coverage\\\", passed=True,\\n+                study=shards[0][\\\"study\\\"], engine=json.loads(next(iter(identities))), registered_repetitions=30,\\n+                sample_count=1350, mutation_sample_count=1200, fanout_sample_count=150,\\n+                setup_pair_count=1200, setup_pairs=setup, groups=results, environments=environments,\\n+                capacity_contract=full.capacity_contract(), input_digests=inputs,\\n+                evidence=[dict(directory=s[\\\"directory\\\"], receipt_sha256=s[\\\"receipt_sha256\\\"]) for s in shards],\\n+                history=\\\"fresh pristine A/B per profile; not the old sequential warm/history distribution\\\",\\n+                deadline_scope=\\\"five hours per worker INCLUDING setup and both complete parity comparisons; 1350 workers\\\",\\n+                total_time_allowance=\\\"6750 worker-hours; not equivalent splitting of old 150-worker/750-hour study\\\",\\n+                scope=\\\"P8-006 isolated mutation/fanout coverage; setup is not new P8-005 or query/P8-008 credit\\\",\\n+                resources_scope=\\\"original worker snapshots, not peaks or process-tree proof\\\",\\n+                statistics_scope=\\\"N30 per group with environment strata; no pooled stable tails\\\",\\n+                release_certification=\\\"not_run\\\", G8=\\\"not_evaluated\\\", task_statuses_changed=False)\\n+\\n+\\n+def aggregate(build_directory, directories, output, root=None):\\n+    out = full.new_directory(output)\\n+    result = dict(schema=SCHEMA, stage_scope=SCOPE, status=\\\"failed\\\", passed=False, release_certification=\\\"not_run\\\")\\n+    try:\\n+        outer, built, binary = validate_build(build_directory, root)\\n+        shards = [validate_shard(path, outer, built, binary, build_directory, root) for path in directories]\\n+        result = combine(shards)\\n+        result[\\\"driver_source\\\"] = outer[\\\"driver_source\\\"]\\n+        result[\\\"profile_build_receipt_sha256\\\"] = file_sha256(Path(build_directory) / \\\"profile-build.json\\\")\\n+    except ERRORS as error:\\n+        result[\\\"error\\\"] = str(error)\\n+    full.write_new(out / \\\"profile-matrix.json\\\", result)\\n+    return result\\n+\\n+\\n+def main():\\n+    parser = argparse.ArgumentParser(description=__doc__)\\n+    sub = parser.add_subparsers(dest=\\\"mode\\\", required=True)\\n+    for mode in (\\\"build\\\", \\\"run\\\", \\\"aggregate\\\"):\\n+        command = sub.add_parser(mode)\\n+        command.add_argument(\\\"--root\\\", type=Path, default=Path.cwd())\\n+        command.add_argument(\\\"--output\\\", type=Path, required=True)\\n+        if mode != \\\"aggregate\\\":\\n+            command.add_argument(\\\"--run-id\\\", required=True)\\n+            command.add_argument(\\\"--attempt\\\", type=int, required=True)\\n+        if mode == \\\"build\\\":\\n+            command.add_argument(\\\"--target-directory\\\", type=Path)\\n+        else:\\n+            command.add_argument(\\\"--build\\\", type=Path, required=True)\\n+        if mode == \\\"run\\\":\\n+            command.add_argument(\\\"--scale\\\", type=int, choices=full.SCALES, required=True)\\n+            command.add_argument(\\\"--shard-index\\\", type=int, required=True)\\n+            command.add_argument(\\\"--mutation-profile\\\", choices=PROFILES + (\\\"fanout\\\",), required=True)\\n+            command.add_argument(\\\"--fanout\\\", type=int, choices=full.FANOUTS)\\n+        if mode == \\\"aggregate\\\":\\n+            command.add_argument(\\\"--inputs\\\", nargs=\\\"+\\\", type=Path, required=True)\\n+    args = parser.parse_args()\\n+    try:\\n+        if args.mode == \\\"build\\\":\\n+            result = build(args.root, args.output, args.run_id, args.attempt, args.target_directory)\\n+        elif args.mode == \\\"run\\\":\\n+            result = run_shard(args.root, args.build, args.output, args.scale, args.shard_index, args.run_id, args.attempt, args.mutation_profile, args.fanout)\\n+        else:\\n+            result = aggregate(args.build, args.inputs, args.output, args.root)\\n+        print(json.dumps({key: result.get(key) for key in (\\\"status\\\", \\\"passed\\\", \\\"error\\\", \\\"sample_count\\\")}))\\n+        return 0 if result.get(\\\"passed\\\") is True else 1\\n+    except ERRORS as error:\\n+        print(str(error), file=sys.stderr)\\n+        return 2\\n+\\n+\\n+if __name__ == \\\"__main__\\\":\\n+    raise SystemExit(main())\"},{\"sha\":\"6d6c6e4362760fb1eb78770efe41b578e6552dc7\",\"filename\":\"scripts/p8_scale_